CREATE TRIGGER search_car_update AFTER UPDATE ON public.cars FOR EACH ROW WHEN (old.name IS DISTINCT FROM new.name OR old.make IS DISTINCT FROM new.make OR old.model IS DISTINCT FROM new.model OR old.year IS DISTINCT FROM new.year OR old.tags IS DISTINCT FROM new.tags OR old.about IS DISTINCT FROM new.about OR old.is_public IS DISTINCT FROM new.is_public OR old.owner_id IS DISTINCT FROM new.owner_id OR old.created_at IS DISTINCT FROM new.created_at) EXECUTE FUNCTION public.queue_search_change('car', 'id');
